-- S5 security review functional follow-ups; real caller roles and rollback-only fixtures.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
set local s1.tap='on';
select no_plan();
\ir s1_fixture.sql
insert into public.participants(room_id,profile_id,name) values('20000000-0000-4000-8000-000000000001','10000006-0000-4000-8000-000000000006','Synthetic F rejoined');
create temporary table s5_review(k text primary key,v jsonb);
grant all on s5_review to authenticated,service_role;
set local role authenticated;
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
select public.set_room_recommendation_area_v2('20000000-0000-4000-8000-000000000001','local-dev-seoul-center',0);
select public.save_my_food_preferences_v2('s5-food-2026-10-18-v1','{"cuisines":["korean","japanese"],"ingredients":[],"forms":[],"spice":null}',0);
select public.begin_room_recommendation_v2('20000000-0000-4000-8000-000000000001','52000000-0000-4000-8000-000000000001','places');
select pg_temp.as_user('10000006-0000-4000-8000-000000000006');
select pg_temp.check(public.mark_food_profile_prompt_v2('shown',0)->>'revision'='1','first shown creates only onboarding state');
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into s5_review values('one',public.claim_recommendation_work_v2('52000000-0000-4000-8000-000000000001'));
select pg_temp.check(public.finalize_recommendation_work_v2('52000000-0000-4000-8000-000000000001',(select (v->>'work_token')::uuid from s5_review where k='one'),'{"places":[]}','[]','rules')->>'source'='rules','first shown by another member does not invalidate pending recommendation');
set local role authenticated;
select pg_temp.as_user('10000006-0000-4000-8000-000000000006');
select public.mark_food_profile_prompt_v2('shown',1);
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
select pg_temp.check(public.validate_my_recommendation_v2('52000000-0000-4000-8000-000000000001')->>'status'='valid','repeat shown does not invalidate completed result');
select pg_temp.check(public.begin_room_recommendation_v2('20000000-0000-4000-8000-000000000001','52000000-0000-4000-8000-000000000002','places')->>'status'='pending','second request is pending');
select pg_temp.as_user('10000002-0000-4000-8000-000000000002');
select public.save_my_food_preferences_v2('s5-food-2026-10-18-v1','{"cuisines":["chinese"],"ingredients":[],"forms":[],"spice":null}',0);
select pg_temp.as_user('10000006-0000-4000-8000-000000000006');
select public.save_my_food_preferences_v2('s5-food-2026-10-18-v1','{"cuisines":["korean"],"ingredients":[],"forms":[],"spice":null}',2);
reset role;
select pg_temp.check(private.s5_weights('20000000-0000-4000-8000-000000000001')='{"korean":1.5,"japanese":0.5,"chinese":1}'::jsonb,'three members contribute bounded equal weights without health');
set local role authenticated;
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
select public.begin_room_recommendation_v2('20000000-0000-4000-8000-000000000001','52000000-0000-4000-8000-000000000003','places');
select pg_temp.as_user('10000002-0000-4000-8000-000000000002');
select public.mark_food_profile_prompt_v2('shown',1);
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into s5_review values('three',public.claim_recommendation_work_v2('52000000-0000-4000-8000-000000000003'));
select pg_temp.check((select v->'keywords'='["korean","chinese","japanese"]'::jsonb from s5_review where k='three'),'worker receives ordered keywords without counts after shown');
select pg_temp.check(not has_function_privilege('authenticated','public.fail_recommendation_work_v2(uuid,uuid)','EXECUTE') and not has_function_privilege('anon','public.fail_recommendation_work_v2(uuid,uuid)','EXECUTE') and has_function_privilege('service_role','public.fail_recommendation_work_v2(uuid,uuid)','EXECUTE'),'only service role has failure RPC execute');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.fail_recommendation_work_v2('52000000-0000-4000-8000-000000000001',(select (v->>'work_token')::uuid from s5_review where k='one'))$q$)='42501','completed ticket cannot be cancelled');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.fail_recommendation_work_v2('52000000-0000-4000-8000-000000000003',gen_random_uuid())$q$)='42501','wrong worker token cannot cancel request');
select public.fail_recommendation_work_v2('52000000-0000-4000-8000-000000000003',(select (v->>'work_token')::uuid from s5_review where k='three'));
select public.fail_recommendation_work_v2('52000000-0000-4000-8000-000000000003',(select (v->>'work_token')::uuid from s5_review where k='three'));
select pg_temp.check(pg_temp.sqlstate_of($q$select public.finalize_recommendation_work_v2('52000000-0000-4000-8000-000000000003',(select (v->>'work_token')::uuid from s5_review where k='three'),'{"places":[]}','[]','rules')$q$)='42501','failed ticket cannot later finalize');
set local role authenticated;
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.begin_room_recommendation_v2('20000000-0000-4000-8000-000000000001','52000000-0000-4000-8000-000000000003','places')$q$)='S5006','failed replay explicitly requires a new ID');
select public.begin_room_recommendation_v2('20000000-0000-4000-8000-000000000001','52000000-0000-4000-8000-000000000004','places');
select public.begin_room_recommendation_v2('20000000-0000-4000-8000-000000000001','52000000-0000-4000-8000-000000000005','places');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.begin_room_recommendation_v2('20000000-0000-4000-8000-000000000001',gen_random_uuid(),'places')$q$)='S5005','one caller cannot exceed five requests per minute');
select pg_temp.as_user('10000002-0000-4000-8000-000000000002');
select pg_temp.check(public.begin_room_recommendation_v2('20000000-0000-4000-8000-000000000001','52000000-0000-4000-8000-000000000006','places')->>'status'='pending','another caller retains room budget after first caller exhausted');
reset role;
select pg_temp.check((select provolatile='s' and pg_get_functiondef(oid) !~ 's5_lock_members|for update|pg_advisory' from pg_proc where oid='public.validate_my_recommendation_v2(uuid)'::regprocedure),'validation is stable and has no write/advisory locks');
delete from private.recommendation_requests;
delete from private.recommendation_usage;
insert into private.recommendation_requests(request_id,caller_id,room_id,purpose,context_hash,expires_at)
select gen_random_uuid(),'10000003-0000-4000-8000-000000000003','20000000-0000-4000-8000-000000000001','places','synthetic',clock_timestamp()+interval '5 minutes' from generate_series(1,30);
set local role authenticated;
select pg_temp.as_user('10000002-0000-4000-8000-000000000002');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.begin_room_recommendation_v2('20000000-0000-4000-8000-000000000001',gen_random_uuid(),'places')$q$)='S5005','room minute budget independently caps at thirty');
reset role;
delete from private.recommendation_requests;
delete from private.recommendation_usage;
insert into private.recommendation_requests(request_id,caller_id,room_id,purpose,context_hash,expires_at,created_at)
select gen_random_uuid(),'10000003-0000-4000-8000-000000000003','20000000-0000-4000-8000-000000000001','places','synthetic',clock_timestamp()+interval '5 minutes',clock_timestamp()-interval '2 hours' from generate_series(1,1000);
set local role authenticated;
select pg_temp.as_user('10000002-0000-4000-8000-000000000002');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.begin_room_recommendation_v2('20000000-0000-4000-8000-000000000001',gen_random_uuid(),'places')$q$)='S5005','room daily budget independently caps at one thousand');
reset role;
delete from private.recommendation_requests;
delete from private.recommendation_usage;
insert into private.recommendation_requests(request_id,caller_id,room_id,purpose,context_hash,expires_at,created_at)
select gen_random_uuid(),'10000002-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002','places','synthetic',clock_timestamp()+interval '5 minutes',clock_timestamp()-interval '2 hours' from generate_series(1,100);
insert into private.recommendation_usage(caller_id,created_at) select '10000002-0000-4000-8000-000000000002',clock_timestamp()-interval '2 hours' from generate_series(1,100);
set local role authenticated;
select pg_temp.as_user('10000002-0000-4000-8000-000000000002');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.begin_room_recommendation_v2('20000000-0000-4000-8000-000000000001',gen_random_uuid(),'places')$q$)='S5005','caller daily budget applies across rooms');
reset role;
select * from finish();
rollback;
